#[inline]
fn destack_net_uds_uds_socket_pair_vm_replay(
    binding: &BindingCallContext,
    context: &mut vm::ExternalCallContext<'_>,
    world: RuntimeWorld,
    sockettype: SocketType,
) -> RuntimeResult<vm::Value> {
    let result = binding.trace().run_binding(
        NET_UDS_UDS_SOCKET_PAIR,
        binding.replay_payload_for(NET_UDS_UDS_SOCKET_PAIR)?,
        context,
        |context| match world {
            RuntimeWorld::Host => {
                platform_vm::destack_net_uds_socket_pair(binding, context, sockettype)
            }
            RuntimeWorld::Simulation => {
                platform_simulation_vm::destack_net_uds_socket_pair(binding, context, sockettype)
            }
        },
        |_context, result| {
            if let Ok(value) = result {
                let result_value: SocketPairVm = value.clone();
                let result_recorded_first = result_value.first;
                let result_recorded_second = result_value.second;
                let result_recorded = SocketPair {
                    first: result_recorded_first,
                    second: result_recorded_second,
                };
                let payload = NetUdsUdsSocketPairReplayRecord {
                    result: Ok(result_recorded),
                };
                return Ok(Some(payload));
            }

            if let Err(error) = result {
                let payload = {
                    let result = Err(TraceError::from(error.as_ref()));
                    NetUdsUdsSocketPairReplayRecord { result }
                };
                return Ok(Some(payload));
            }

            Ok(None)
        },
        |_context, payload| {
            // replay result
            match payload.result {
                Ok(value) => {
                    let vm_result_first = value.first;
                    let vm_result_second = value.second;
                    let vm_result = SocketPair {
                        first: vm_result_first,
                        second: vm_result_second,
                    };
                    Ok(vm_result)
                }
                Err(error) => Err(Box::<RuntimeError>::from(error)),
            }
        },
    );
    let result = encode_destack_net_uds_uds_socket_pair_result(context, result)?;
    Ok(result)
}

